{'content': '// 3D Printable Towel Hook
// Designed for a single M3 flat head screw
// Print orientation: Flat on side (XY plane) for maximum strength

$fn = 64;

// --- Dimenions ---
hook_width = 16;       // Thickness of the hook (extrusion height)
wall_height = 45;      // Height of the back plate
stick_out = 32;        // How far it sticks out from wall
thickness = 9;         // General thickness of the arm
screw_y_pos = 28;      // Height of screw hole from bottom

// M3 Screw dimensions
screw_shaft_d = 3.4;
screw_head_d = 6.8;    // Slightly overlapping standard 6mm head for easier fit
screw_sink_depth = 4.0;// How deep the head is sunk into the body

module teardrop_cutout(d, h) {
    // Creates a horizontal tear-drop shape along the X-axis
    // The point points towards +Z (upwards during printing)
    r = d / 2;
    rotate([0, 90, 0]) {
        union() {
            cylinder(r=r, h=h, center=false);
            linear_extrude(h=h, center=false)
                polygon([
                    [r * cos(45), r * sin(45)],
                    [0, r / sin(45)], // Tip peak
                    [-r * cos(45), r * sin(45)]
                ]);
        }
    }
}

module countersink_cutout(d_shaft, d_head, h_total) {
    // Complex cutout for screw head + shaft
    // Oriented along X axis

    // 1. Shaft pass-through (Teardrop for printability)
    translate([-1, 0, 0])
        teardrop_cutout(d=d_shaft, h=h_total + 2);

    // 2. Countersink Cone
    // Since we are printing horizontally, a perfect cone has overhangs.
    // However, M3 is small enough that a standard cone usually works fine 
    // or we can step it. For a "flat head" screw, it's conical.
    // We will position it based on the intended screw seat depth.

    // We want the screw head to seat at x = (back_thickness - screw_sink_depth).
    // Let's assume back thickness at the hole is ~10mm.
    seat_x = 5; 

    translate([seat_x, 0, 0])
    rotate([0, 90, 0])
        cylinder(d1=d_shaft, d2=d_head * 1.5, h=15); // Wide cone out
}

module hook_profile() {
    difference() {
        hull() {
            // Top of wall mount
            translate([thickness/2, wall_height - thickness/2]) 
                circle(d=thickness);

            // Bottom "Heel"
            translate([thickness/2, thickness/2]) 
                circle(d=thickness);

            // Curve bottom
            translate([stick_out - thickness/2, 10]) 
                circle(d=thickness);

            // Tip
            translate([stick_out - 3, 24]) 
                circle(d=thickness*0.7);
        }

        // Flatten the back (Wall interface)
        translate([-thickness, -10]) 
            square([thickness, wall_height + 20]);

        // Flatten the tip slightly? No, round is good.
    }
}

module main_hook() {
    difference() {
        // Base Body
        linear_extrude(height=hook_width, convexity=10)
            hook_profile();

        // Screw Hole
        // Positioned in the center of the width (Z) and at screw_y_pos
        translate([0, screw_y_pos, hook_width/2])
            countersink_cutout(d_shaft=screw_shaft_d, d_head=screw_head_d, h_total=20);
    }
}

main_hook();
'}

{'content': '// 3D Printable Towel Hook
// Designed for a single M3 flat head screw
// Print orientation: Flat on side (XY plane) for maximum strength

$fn = 64;

// --- Dimenions ---
hook_width = 16;       // Thickness of the hook (extrusion height)
wall_height = 45;      // Height of the back plate
stick_out = 32;        // How far it sticks out from wall
stem_thickness = 11;   // Thickness of the vertical arm (increased for screw clearance)
screw_y_pos = 28;      // Height of screw hole from bottom

// M3 Screw dimensions
screw_shaft_d = 3.5;   // Clearance for M3
screw_head_d = 6.4;    // Head diameter (standard is ~6mm, usually slightly larger clearance)
screw_cone_h = (screw_head_d - screw_shaft_d) / 2; // Height of the conical part (45 deg wall)

module teardrop_polygon(r) {
    polygon([
        [r * cos(0), r * sin(0)],
        [r * cos(45), r * sin(45)],
        [0, r / sin(45)], // Peak
        [-r * cos(45), r * sin(45)],
        [-r * cos(0), r * sin(0)],
        [-r * cos(-45), r * sin(-45)],
        [0, -r],          // Bottom round
        [r * cos(-45), r * sin(-45)]
    ]);
}

module teardrop_cutout(d, h) {
    // Oriented along X axis for the hole
    // Shape defined in YZ plane
    // Peak points towards +Z

    r = d / 2;
    rotate([0, 90, 0])
    linear_extrude(height=h, center=false)
    rotate([0, 0, 90]) // Rotate polygon so peak (which polygon assumes is Y positive) points to Z positive
    // Polygon standard orientation in 2D is usually Y "up".
    // After replace [0,90,0], the local X is global Z? No.
    // Let's rely on standard primitives to be safe.

    // Simpler Teardrop approach:
    // Cylinder + Box rotated 45 deg cut
    intersection() { // Wait, union.
    }

    // Explicit polygon construction is safer
        polygon([
            [r, 0],
            [r * cos(45), r * sin(45)],
            [0, r * 1.5], // Tip (approx) - actually r/sin(45) ~ 1.414*r
            [-r * cos(45), r * sin(45)],
            [-r, 0],
            [-r, -r],
            [r, -r]
        ]);
        // This is a teardrop profile in 2D (along Y "up").
        // Rotate([0,0,90]) aligns Y "up" to X "up".
        // Then convert to 3D via rotate([0,90,0])... transform math is headache.

        // Let's use hull() of cylinder + rotated cube?
}

module simple_teardrop(d, h) {
    r = d/2;
    rotate([0, 90, 0]) // Extrude along X
    linear_extrude(h)
    hull() {
        circle(r=r);
        translate([0, r/2]) square([0.1, 0.1]); // Dummy center
        // Just a triangle on top
        polygon([
            [r * cos(45), r * sin(45)],
            [0, r / sin(45)],
            [-r * cos(45), r * sin(45)]
        ]);
    }
}

module screw_hole_cutout() {
    // 1. Shaft (Teardrop style)
    // Goes from X=-1 to Seat Position
    seat_x = 4; // 4mm of plastic holding the screw against the wall

    translate([-1, screw_y_pos, hook_width/2]) {
        // Shaft Passage
        simple_teardrop(d=screw_shaft_d, h=seat_x + 2);
    }

    // 2. Head Countersink (Conical) + Access Hole
    // Starts at seat_x.

    translate([seat_x, screw_y_pos, hook_width/2])
    rotate([0, 90, 0]) {
        hull() {
             // Start of cone (dia = shaft)
             translate([0, 0, 0]) cylinder(d=screw_shaft_d, h=0.1);
             // End of cone (dia = head)
             // Standard flat head angle is 90 deg. 
             // Height = radius difference.
             translate([0, 0, screw_cone_h]) cylinder(d=screw_head_d, h=0.1);
        }
        // Access Cylinder (clearance for head/screwdriver)
        translate([0, 0, screw_cone_h]) 
            cylinder(d=screw_head_d, h=25);
    }
}

module hook_shape() {
    difference() {
        hull() {
            // Top of wall mount
            translate([stem_thickness/2, wall_height - stem_thickness/2]) 
                circle(d=stem_thickness);

            // Bottom "Heel"
            translate([stem_thickness/2, stem_thickness/2]) 
                circle(d=stem_thickness);

            // Curve bottom (tapering slightly usually looks better, but constant is strong)
            translate([stick_out - 6, 8]) 
                circle(d=8);

            // Tip
            translate([stick_out, 24]) 
                circle(d=6);
        }

        // Flatten the back (Wall interface)
        translate([-stem_thickness, -10]) 
            square([stem_thickness, wall_height + 20]);
    }
}

difference() {
    linear_extrude(height=hook_width, convexity=10)
        hook_shape();

    screw_hole_cutout();
}
'}

{'content': '// 3D Printable Towel Hook
// Designed for a single M3 flat head screw
// Print orientation: Flat on side (XY plane) for maximum strength

$fn = 64;

// --- Dimenions ---
hook_width = 16;       // Thickness of the hook (extrusion height)
wall_height = 45;      // Height of the back plate
stick_out = 32;        // How far it sticks out from wall
stem_thickness = 11;   // Thickness of the vertical arm
screw_y_pos = 28;      // Height of screw hole from bottom

// M3 Screw dimensions
screw_shaft_d = 3.5;
screw_head_d = 6.8;    // Clearance for head
screw_cone_h = (screw_head_d - screw_shaft_d) / 2; // Approx 1.65mm

// --- Modules ---

module teardrop_shape_2d(r) {
    // Defines a teardrop logic where the 'point' is aimed at Global Z
    // AFTER rotation of [0, 90, 0].
    // RotY(90) maps Local X to Global -Z.
    // So to point Global +Z, we need Local -X.
    hull() {
        circle(r=r);
        // Point at -X
        translate([-r/sin(45), 0]) square([0.1, 0.1], center=true); 
    }
}

// Actually, calculating the point offset is annoying.
// Let's just define it standard (Point +Y) and rotate properly.
// Standard Teardrop (Point +Y):
// If Rotated [0, 90, 0]: Y stays Y. Point stays Horizontal. Bad.
// If Rotated [0, 90, 0] * [0, 0, 90]?
// Rotate Z(90) first: X->Y, Y->-X.
// Then Y(90): ...
// Let's just construct the polygon manually in the loop.

module horizontal_teardrop(d, h) {
    r = d/2;
    // We want a hole along X axis.
    // We want the peak in +Z axis.
    // Let's construct it directly in 3D using linear_extrude along X (using rotation).

    rotate([0, 90, 0]) // Extrude becomes X axis
    linear_extrude(height=h, center=false)
    polygon([
        [0, r],                   // Top of circle (Global Y+)
        [r * cos(45), r * sin(45)],
        [r * 1.414, 0],           // Peak (Global Z+ ... wait, check mapping)
        [r * cos(45), -r * sin(45)],
        [0, -r],
        [-r * cos(45), -r * sin(45)],
        [-r * 1.414, 0],          // Bottom Peak?
        [-r * cos(45), r * sin(45)]
    ]);
    // The Matrix check again:
    // Cylinder along Z. Profile in XY.
    // Rotate [0, 90, 0].
    // New X = Old Z.
    // New Y = Old Y.
    // New Z = -Old X.

    // We want Peak at New Z (+).
    // So we need Peak at Old X (-).
    // So the point in the 2D polygon must be at x < 0.

    // Correct Polygon for Z-extrusion before rotation:
    // Circle at origin.
    // Point at [-r, 0] or further negative.

}

module teardrop_x_aligned(d, h) {
    r = d/2;
    rotate([0, 90, 0])
    linear_extrude(height=h)
    hull() {
        circle(r=r);
        // Peak at Local -X (which maps to Global +Z)
        polygon([
            [0, r * sin(45)],
            [-r * 1.5, 0], // The tip
            [0, -r * sin(45)]
        ]);
    }
}

module screw_hole_cutout() {
    seat_x = 4; // Thickness of wall behind screw

    translate([-1, screw_y_pos, hook_width/2]) {
        // 1. Shaft Passage (Teardrop)
        teardrop_x_aligned(d=screw_shaft_d, h=seat_x + 2);
    }

    translate([seat_x, screw_y_pos, hook_width/2]) {
        // 2. Head Countersink (Cone)
        // Since we can't easily teardrop a cone, and it's short,
        // we use a standard cylinder cone.
        // It's inside the body, bridging is minimal.
        rotate([0, 90, 0])
            cylinder(d1=screw_shaft_d, d2=screw_head_d, h=screw_cone_h);

        // 3. Head Access (Teardrop)
        // Starts after cone.
        translate([screw_cone_h, 0, 0])
            teardrop_x_aligned(d=screw_head_d, h=30);
    }
}


module hook_shape() {
    difference() {
        hull() {
            // Top of wall mount
            translate([stem_thickness/2, wall_height - stem_thickness/2]) 
                circle(d=stem_thickness);

            // Bottom "Heel"
            translate([stem_thickness/2, stem_thickness/2]) 
                circle(d=stem_thickness);

            // Curve bottom 
            translate([stick_out - 6, 8]) 
                circle(d=9);

            // Tip
            translate([stick_out, 24]) 
                circle(d=6);
        }

        // Flatten the back
        translate([-stem_thickness, -10]) 
            square([stem_thickness, wall_height + 20]);
    }
}

difference() {
    linear_extrude(height=hook_width, convexity=10)
        hook_shape();

    screw_hole_cutout();
}
'}
